(* [comment removed for export] *)
Fixpoint art_qsep (bs : list art_qbatch) : Prop :=
  match bs with
  | [] => True
  | b :: r => 0 <= qb_addr b /\ qb_addr b + 8192 < 2 ^ 64 /\ Forall (fun b' => apart (qb_addr b) 8192 (qb_addr b') 8192) r /\ art_qsep r
  end.

